UPDATE tool_execution
SET status = #{status},
    result_json = #{resultJson},
    lease_token = NULL,
    lease_until = NULL,
    revision = revision + 1,
    finished_at = #{finishedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND revision = #{revision}
  AND status = 'RUNNING'
  AND lease_token = #{leaseToken}
  AND #{status} IN ('SUCCEEDED', 'FAILED', 'UNKNOWN')
